// SPDX-License-Identifier: GPL-3.0-only
// Exact Updater.install OTA target-family regression with mock MIDI discovery.
// Run: node web/test_install_nightly_ota_model.mjs [path-to-fm1ota.js]
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { Script } from "node:vm";
import { sameKeyboard } from "./fm1ota.js";

const path = process.argv[2] || new URL("./fm1ota.js", import.meta.url);
const text = readFileSync(path, "utf8");
const i = text.indexOf("  async install(image, product, onStep) {");
const j = text.indexOf("\n  // step 2 with the loader", i);
assert.ok(i >= 0 && j > i, "Updater.install source anchors absent");
const method = text.slice(i, j).trim();
const install = new Script("({" + method + "}).install").runInNewContext({
  UPGRADE: [0xf0, 0x22, 0x24, 0x35, 0x7f, 0xf7],
  sleep: async () => {},
  IS_OTA: (id) => /^ota-/i.test(id.model),
  sameKeyboard,
  fail: (code, message, detail = "") => Object.assign(new Error(message), { code, detail }),
});
assert.equal(typeof install, "function");

async function simulate(spec) {
  const model = spec.model || "SMK-37 Pro";
  const product = model + "_900";
  const state = { writes: [], filters: [], rebootFilters: [], closed: 0, upgradeCalls: 0 };
  const dev = (m) => ({
    id: { model: m, text: m + "_900" },
    name: m,
    link: { send() { state.upgradeCalls++; }, close() { state.closed++; } },
  });
  let loaderSearch = true;
  const updater = {
    async find(filter) {
      const d = dev(spec.running || model);
      return filter(d.id) ? d : null;
    },
    // Nightly transition wait snapshots prior matching ports; mock has none.
    async matchingPorts() { return []; },
    async serve() { return { finished: true, served: 1 }; },
    async waitFor(filter) {
      if (loaderSearch) {
        loaderSearch = false;
        for (const name of spec.loaders) {
          const d = dev(name);
          const eligible = filter(d.id);
          state.filters.push([name, eligible]);
          if (eligible || spec.ignoreFilter) return d;
        }
        return null;
      }
      // Reboot discovery must skip another plugged-in keyboard's running app.
      for (const name of (spec.reboots || [model])) {
        const d = dev(name);
        const eligible = filter(d.id);
        state.rebootFilters.push([name, eligible]);
        if (eligible || spec.ignoreRebootFilter) return d;
      }
      return null;
    },
    async write(d) {
      state.writes.push(d.id.model);
      return { finished: true };
    },
  };
  try { state.returned = await install.call(updater, new Uint8Array([1]), product, () => {}); }
  catch (e) { state.error = e.code || e.message; }
  return state;
}

const cases = [
  { name: "Pro ignores unrelated FM-1 after loader write", loaders: ["ota-SMK-37 Pro"], reboots: ["FM-1", "SMK-37 Pro"], rebootAllowed: [false, true], write: "ota-SMK-37 Pro" },
  { name: "Pro wrong-family-only reboot is not success", loaders: ["ota-SMK-37 Pro"], reboots: ["FM-1"], rebootAllowed: [false], wrote: "ota-SMK-37 Pro", error: "noreturn" },
  { name: "FM-1 ignores unrelated Pro after loader write", model: "FM-1", loaders: ["ota-FM-1"], reboots: ["SMK-37 Pro", "FM-1"], rebootAllowed: [false, true], write: "ota-FM-1" },
  { name: "wrong-family reboot discovery bypass still rejected", loaders: ["ota-SMK-37 Pro"], reboots: ["FM-1"], ignoreRebootFilter: true, rebootAllowed: [false], wrote: "ota-SMK-37 Pro", error: "noreturn" },
  { name: "legitimate same-family Elite reboot keeps mismatch report", loaders: ["ota-SMK-37 Pro"], reboots: ["SMK-37 Elite"], rebootAllowed: [true], wrote: "ota-SMK-37 Pro", error: "mismatch" },
  { name: "Pro skips unrelated FM-1 loader", loaders: ["ota-FM-1", "ota-SMK-37 Pro"], write: "ota-SMK-37 Pro" },
  { name: "Pro never writes FM-1-only loader", loaders: ["ota-FM-1"], error: "noloader" },
  { name: "FM-1 never writes Pro-only loader", model: "FM-1", loaders: ["ota-SMK-37 Pro"], error: "noloader" },
  { name: "FM-1 skips unrelated Pro loader", model: "FM-1", loaders: ["ota-SMK-37 Pro", "ota-FM-1"], write: "ota-FM-1" },
  { name: "Elite loader alias accepted for Pro", loaders: ["ota-SMK-37 Elite"], write: "ota-SMK-37 Elite" },
  { name: "MKE loader alias accepted for Pro", loaders: ["ota-MKE-P37"], write: "ota-MKE-P37" },
  { name: "Starrykey loader alias accepted for Pro", loaders: ["ota-STARRYKEY-37 Play"], write: "ota-STARRYKEY-37 Play" },
  { name: "independent check rejects wrong loader from discovery", loaders: ["ota-FM-1"], ignoreFilter: true, error: "model" },
  { name: "independent check rejects non-OTA port from discovery", loaders: ["SMK-37 Pro"], ignoreFilter: true, error: "model" },
  { name: "wrong running keyboard rejected", running: "FM-1", loaders: ["ota-SMK-37 Pro"], error: "model" },
  { name: "FM-1 normal OTA supported", model: "FM-1", loaders: ["ota-FM-1"], write: "ota-FM-1" },
  { name: "ordinary port skipped during OTA discovery", loaders: ["SMK-37 Pro", "ota-SMK-37 Pro"], write: "ota-SMK-37 Pro" },
  { name: "case-insensitive SMK alias supported", loaders: ["OTA-smk-37 elite"], write: "OTA-smk-37 elite" },
];
let passed = 0;
for (const c of cases) {
  const r = await simulate(c);
  if (c.write) {
    assert.deepEqual(r.writes, [c.write], c.name + " write target");
    assert.equal(r.error, undefined, c.name + " unexpected error");
    assert.equal(r.returned, (c.model || "SMK-37 Pro") + "_900", c.name + " final identity");
  } else {
    assert.equal(r.error, c.error, c.name + " expected error");
    assert.deepEqual(r.writes, c.wrote ? [c.wrote] : [], c.name + " expected write disposition");
  }
  if (c.rebootAllowed) assert.deepEqual(r.rebootFilters.map((x) => x[1]), c.rebootAllowed, c.name + " reboot family filter");
  passed++;
  console.log("PASS " + c.name);
}
console.log("PASS " + passed + " OTA-loader source-exact mock regressions; no device used");

/* SPDX-License-Identifier: GPL-3.0-only */
/* Chicago Fx Type / Edit 1 / Edit 2 — SEND bridge + Crush/Ring/EQ/Cho/Ens/Phaser/
 * SDly/BPM/Hall/GateRev insert (FCDC-205).
 *
 * Chicago AU is a per-voice insert strip (12 algorithms). Product audio is a
 * shared T_FX fxbus + per-part T_MIX sends, plus Crush / Ring / EQ / Cho / Ens /
 * Phaser / Short Delay / BPM Delay / Hall / GateRev inserts on the 303 dry voice
 * (chicago_crush.h / chicago_ring.h / chicago_eq.h / chicago_cho.h /
 * chicago_ens.h / chicago_phaser.h / chicago_sdly.h / chicago_bpmdly.h /
 * chicago_hall.h / chicago_gaterev.h). All 12 AU types are supported (Off/Comp
 * SEND; the rest insert).
 *
 * Supported SEND / master stage (labeled SEND FX in the UI):
 *   Off, Comp
 * Supported INSERT (per-voice DSP, not Mix theft):
 *   Crush (Decimator), Ring Mod, EQ, Cho/Flg, Ensemble, Phaser, Short Delay,
 *   BPM Delay, Hall, Gate Rev
 *
 * Stored in sound_t after bass303 DSP pots (CHI_FX_*). Not consumed by
 * bass303_set. Global Comp theft is intentional and labeled.
 * Miami wobble stays on WBL1 — not mapped here. */
#pragma once
#include <stdint.h>
#include "../dsp/x0x_param.h"

enum {
    /* After Chicago Arp 23..26 (CHI_ARP_NPARAMS_END == 27). Do not retarget arp/ADSR. */
    CHI_FX_TYPE = 27,
    CHI_FX_EDIT1,
    CHI_FX_EDIT2,
    CHI_FX_END /* SEND FX last index+1; Chicago aux (PBend/Damp) continues at 30..31 */
};

/* Canonical Chicago Type indices (AU Fx Type 0..11). */
enum {
    CHI_FX_OFF = 0,
    CHI_FX_EQ,
    CHI_FX_COMP,
    CHI_FX_DECIM, /* Crush — per-voice insert (chicago_crush.h) */
    CHI_FX_RING,
    CHI_FX_CHO,
    CHI_FX_ENS,
    CHI_FX_PHASER,
    CHI_FX_SHORT_DLY,
    CHI_FX_BPM_DLY,
    CHI_FX_HALL,
    CHI_FX_GATE_REV,
    CHI_FX_NTYPES
};

/* Which Mix / fxbus fields a map write touches. */
enum {
    CHI_FX_W_MX_REV = 1u << 0,
    CHI_FX_W_MX_DLY = 1u << 1,
    CHI_FX_W_COMP = 1u << 2,
    CHI_FX_W_DIST = 1u << 3,
    CHI_FX_W_DRIVE = 1u << 4,
    CHI_FX_W_DL_TIME = 1u << 5,
    CHI_FX_W_DL_LVL = 1u << 6,
    CHI_FX_W_RV_DEC = 1u << 7,
    CHI_FX_W_RV_LVL = 1u << 8,
    CHI_FX_W_CLEAR_SENDS = 1u << 9 /* MX_REV=MX_DLY=0 for this 303 part */
};

typedef struct {
    uint16_t touch; /* CHI_FX_W_* */
    uint8_t mx_rev, mx_dly;
    uint8_t fx_comp, fx_dist, fx_drive;
    uint8_t fx_dl_time, fx_dl_level;
    uint8_t fx_rv_decay, fx_rv_level;
} chicago_fx_out_t;

/* UI names: Crush/Ring/EQ/Cho/Ens/Phas/SDly/BPM/Hall/Gate are plain insert names.
 * Page title SEND FX still covers Comp; remaining types are insert.
 * Tables in chicago_param_tables.c (one copy for engine.o + x0x.o). */
extern const char *const CHI_FX_TYPE_N[CHI_FX_NTYPES];

extern const x0x_param_t CHI_FX_PARAMS[3];

static inline int chi_fx_is_insert(uint8_t type)
{
    return type == CHI_FX_DECIM || type == CHI_FX_RING || type == CHI_FX_EQ ||
           type == CHI_FX_CHO || type == CHI_FX_ENS || type == CHI_FX_PHASER ||
           type == CHI_FX_SHORT_DLY || type == CHI_FX_BPM_DLY || type == CHI_FX_HALL ||
           type == CHI_FX_GATE_REV;
}

static inline int chi_fx_supported(uint8_t type)
{
    switch (type) {
    case CHI_FX_OFF:
    case CHI_FX_COMP:
    case CHI_FX_DECIM:     /* insert — chicago_crush.h */
    case CHI_FX_RING:      /* insert — chicago_ring.h */
    case CHI_FX_EQ:        /* insert — chicago_eq.h */
    case CHI_FX_CHO:       /* insert — chicago_cho.h */
    case CHI_FX_ENS:       /* insert — chicago_ens.h */
    case CHI_FX_PHASER:    /* insert — chicago_phaser.h */
    case CHI_FX_SHORT_DLY: /* insert — chicago_sdly.h */
    case CHI_FX_BPM_DLY:   /* insert — chicago_bpmdly.h */
    case CHI_FX_HALL:      /* insert — chicago_hall.h */
    case CHI_FX_GATE_REV:  /* insert — chicago_gaterev.h */
        return 1;
    default:
        return 0;
    }
}

static inline int chi_fx_is_not_yet(uint8_t type)
{
    return type < CHI_FX_NTYPES && !chi_fx_supported(type);
}

/* Factory / AU 0..255 → Type 0..11 (round). */
static inline uint8_t chi_fx_type_from_byte(uint8_t v)
{
    return (uint8_t)(((uint32_t)v * (CHI_FX_NTYPES - 1u) + 127u) / 255u);
}

static inline uint8_t chi_fx_edit_from_byte(uint8_t v)
{
    return (uint8_t)(((uint32_t)v * 127u + 127u) / 255u);
}

static inline void chi_fx_decode_factory(const uint8_t pots[3], uint8_t out[3])
{
    out[0] = chi_fx_type_from_byte(pots[0]);
    out[1] = chi_fx_edit_from_byte(pots[1]);
    out[2] = chi_fx_edit_from_byte(pots[2]);
}

/* Map Type+edits → Mix/fxbus writes. Off returns touch=0 (inactive: do not
 * wipe factory Mix on load). NOT_YET returns CLEAR_SENDS only when clear_ny=1
 * (user just selected an unavailable type). Supported types always write. */
static inline void chicago_fx_map(uint8_t type, uint8_t e1, uint8_t e2, int clear_ny,
                                 chicago_fx_out_t *o)
{
    uint8_t send;
    o->touch = 0;
    o->mx_rev = o->mx_dly = 0;
    o->fx_comp = o->fx_dist = o->fx_drive = 0;
    o->fx_dl_time = o->fx_dl_level = 0;
    o->fx_rv_decay = o->fx_rv_level = 0;
    if (type >= CHI_FX_NTYPES)
        type = CHI_FX_OFF;
    if (type == CHI_FX_OFF)
        return;
    if (chi_fx_is_insert(type)) {
        /* Crush / Ring / EQ / Cho / Ens / Phaser / SDly / BPM / Hall / GateRev:
         * clear part sends so Mix does not smear the insert; audio path applies
         * DSP from sound_t FX pots. */
        o->touch = CHI_FX_W_CLEAR_SENDS;
        return;
    }
    if (chi_fx_is_not_yet(type)) {
        if (clear_ny)
            o->touch = CHI_FX_W_CLEAR_SENDS;
        return;
    }
    send = e1;
    (void)e2;
    switch (type) {
    case CHI_FX_COMP:
        /* Global master glue — not per-voice insert. */
        o->touch = CHI_FX_W_COMP | CHI_FX_W_CLEAR_SENDS;
        o->fx_comp = send;
        break;
    default:
        break;
    }
}

/* Part index for 303 voice 0/1 (PART_303A + voice). */
static inline int chi_fx_mix_part(int voice)
{
    return 2 + (voice & 1); /* PART_303A=2, PART_303B=3 */
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* The BREAK part's default built-in loops, played by this firmware's own 909
 * (dsp/drum909.c) on the host at build time: two bars each at 96 BPM, a groove and a busier
 * fill. No recording ships: the loops are this code's output. Written as the break bank
 * header (the same format tools/gen_break_bank.py writes for an opt-in bank of WAVs):
 * IMA ADPCM, mono, 44100 Hz (no downsampling, no length cut), the format of the user sample slots.
 *   gen_builtin_break OUT.h [EXPORT_DIR]
 * EXPORT_DIR receives the same loops as WAV and ADPCM, so they can be installed
 * without living in the firmware image. The ADPCM is the header's bytes, uncut. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "dsp/drum909.h"

#define BPM 96.0
#define RATE 44100
#define BARS 2
#define STEPS (16 * BARS)

/* step strings: x = hit, X = accented hit, g = ghost (soft), . = rest */
typedef struct { int voice; const char *s; } lane_t;
static const lane_t GROOVE[] = {
    {DR_BD, "X.....x...x.....X.....x..x......"},
    {DR_SD, "....X..g.g..X..g....X..g.g..X.g."},
    {DR_CH, "x.x.x.x.x.x.x.x.x.x.x.x.x.x.x.x."},
    {DR_OH, "...............x...............x"},
    {DR_RD, "................................"},
};
static const lane_t FILL[] = {
    {DR_BD, "X.....x...x.x...X..x..x...x.x..."},
    {DR_SD, "....X..g.g.gX.gg....X.gX.gX.XgXX"},
    {DR_CH, "x.x.x.xxx.x.x.x.x.xxx.x.x.x....."},
    {DR_OH, ".......x.......x.......x........"},
    {DR_LT, "............................x..."},
    {DR_MT, "..........................x....."},
    {DR_HT, "........................x......."},
    {DR_CR, "................................"},
};

static int16_t *render(const lane_t *L, int nl, uint32_t *frames)
{
    static drum909_t d;
    float dry[256], rev[256], dly[256];
    double spb = RATE * 60.0 / BPM / 4.0;            /* samples per 16th */
    uint32_t total = (uint32_t)(spb * STEPS + 0.5), pos = 0, i;
    int16_t *out = malloc(sizeof(int16_t) * total);
    int step = 0;
    drum909_init(&d);
    while (pos < total) {
        uint32_t next = step < STEPS ? (uint32_t)(spb * step + 0.5) : total, n;
        if (pos >= next && step < STEPS) {
            int l;
            for (l = 0; l < nl; l++) {
                char c = L[l].s[step];
                if (c == 'x' || c == 'X' || c == 'g')
                    drum909_trigger(&d, L[l].voice, c == 'X' ? 1.0f : c == 'g' ? 0.35f : 0.75f);
            }
            step++;
            continue;
        }
        n = next - pos;
        if (n > 256)
            n = 256;
        memset(dry, 0, sizeof dry);
        memset(rev, 0, sizeof rev);
        memset(dly, 0, sizeof dly);
        drum909_render(&d, dry, rev, dly, (int)n);
        for (i = 0; i < n; i++) {
            float v = dry[i] * 1.6f;                   /* a loop is normalised, like a sampled break */
            v = v > 1.0f ? 1.0f : v < -1.0f ? -1.0f : v;
            out[pos + i] = (int16_t)(v * 32767.0f);
        }
        pos += n;
    }
    *frames = total;
    return out;
}

static const int16_t STEP_T[89] = {
    7, 8, 9, 10, 11, 12, 13, 14, 16, 17, 19, 21, 23, 25, 28, 31, 34, 37, 41, 45, 50, 55, 60, 66, 73, 80, 88, 97,
    107, 118, 130, 143, 157, 173, 190, 209, 230, 253, 279, 307, 337, 371, 408, 449, 494, 544, 598, 658, 724, 796,
    876, 963, 1060, 1166, 1282, 1411, 1552, 1707, 1878, 2066, 2272, 2499, 2749, 3024, 3327, 3660, 4026, 4428,
    4871, 5358, 5894, 6484, 7132, 7845, 8630, 9493, 10442, 11487, 12635, 13899, 15289, 16818, 18500, 20350,
    22385, 24623, 27086, 29794, 32767};
static const int8_t IDX_T[8] = {-1, -1, -1, -1, 2, 4, 6, 8};

/* IMA ADPCM at the render rate (44.1 kHz) from predictor 0 / index 0 (tools/sampleio.py's encoder) */
static uint8_t *adpcm(const int16_t *x, uint32_t n, uint32_t *ns)
{
    uint32_t m = n, i;
    uint8_t *o = calloc(1, m / 2 + 1);
    int pred = 0, idx = 0;
    for (i = 0; i < m; i++) {
        int s = x[i], step = STEP_T[idx], diff = s - pred, code = 0, vd = step >> 3;
        if (diff < 0) {
            code = 8;
            diff = -diff;
        }
        if (diff >= step) { code |= 4; diff -= step; vd += step; }
        if (diff >= step >> 1) { code |= 2; diff -= step >> 1; vd += step >> 1; }
        if (diff >= step >> 2) { code |= 1; vd += step >> 2; }
        pred = code & 8 ? pred - vd : pred + vd;
        pred = pred > 32767 ? 32767 : pred < -32768 ? -32768 : pred;
        idx += IDX_T[code & 7];
        idx = idx < 0 ? 0 : idx > 88 ? 88 : idx;
        if (i & 1)
            o[i >> 1] |= (uint8_t)(code << 4);
        else
            o[i >> 1] = (uint8_t)code;
    }
    *ns = m;
    return o;
}

static void write_raw(const char *path, const uint8_t *d, uint32_t n)
{
    FILE *f = fopen(path, "wb");
    if (!f)
        return;
    fwrite(d, 1, n, f);
    fclose(f);
}

static void write_wav(const char *path, const int16_t *x, uint32_t n)
{
    FILE *f = fopen(path, "wb");
    uint32_t data = n * 2u, riff = 36u + data, sixteen = 16u, rate = RATE, bps = RATE * 2u;
    uint16_t pcm = 1, ch = 1, bits = 16, block = 2;
    if (!f)
        return;
    fwrite("RIFF", 1, 4, f);
    fwrite(&riff, 4, 1, f);
    fwrite("WAVEfmt ", 1, 8, f);
    fwrite(&sixteen, 4, 1, f);
    fwrite(&pcm, 2, 1, f);
    fwrite(&ch, 2, 1, f);
    fwrite(&rate, 4, 1, f);
    fwrite(&bps, 4, 1, f);
    fwrite(&block, 2, 1, f);
    fwrite(&bits, 2, 1, f);
    fwrite("data", 1, 4, f);
    fwrite(&data, 4, 1, f);
    fwrite(x, 2, n, f);
    fclose(f);
}

static void emit(FILE *f, const char *name, const uint8_t *d, uint32_t ns)
{
    uint32_t i, nb = (ns + 1) / 2;
    fprintf(f, "#define %s_N %uu\nstatic const uint8_t %s[%u] = {", name, ns, name, nb);
    for (i = 0; i < nb; i++)
        fprintf(f, "%s%u,", i % 24 ? "" : "\n    ", d[i]);
    fprintf(f, "\n};\n");
}

int main(int argc, char **argv)
{
    uint32_t fa, fb, na, nb;
    int16_t *a = render(GROOVE, (int)(sizeof GROOVE / sizeof GROOVE[0]), &fa);
    int16_t *b = render(FILL, (int)(sizeof FILL / sizeof FILL[0]), &fb);
    uint8_t *ea = adpcm(a, fa, &na), *eb = adpcm(b, fb, &nb);
    FILE *f = fopen(argc > 1 ? argv[1] : "x0x_builtin_break.h", "w");
    if (!f)
        return 1;
    fprintf(f, "/* Generated by tools/gen_builtin_break.c -- do not edit. The BREAK part's default\n"
               " * built-in loops: two bars at %g BPM played by this firmware's 909 port; IMA ADPCM,\n"
               " * mono, 44100 Hz. */\n#pragma once\n#include <stdint.h>\n"
               "#define X0X_NBREAKS 2\n#define X0X_BREAK_RATE 44100u\n", BPM);
    emit(f, "X0X_BREAK_0", ea, na);
    emit(f, "X0X_BREAK_1", eb, nb);
    fprintf(f, "typedef struct { const char *name; const uint8_t *adpcm; uint32_t n; uint8_t bars; } x0x_break_t;\n"
               "static const x0x_break_t X0X_BREAKS[X0X_NBREAKS] = {\n"
               "    {\"909 GR\", X0X_BREAK_0, X0X_BREAK_0_N, %d},\n    {\"909 FL\", X0X_BREAK_1, X0X_BREAK_1_N, %d},\n};\n",
            BARS, BARS);
    fclose(f);
    printf("builtin break: A %u + B %u samples, %u bytes of flash\n", na, nb, (na + 1) / 2 + (nb + 1) / 2);
    if (argc > 2) {
        char path[512];
        FILE *m;
        if (snprintf(path, sizeof path, "%s/909GR.wav", argv[2]) >= (int)sizeof path)
            return 1;
        write_wav(path, a, na);
        snprintf(path, sizeof path, "%s/909FL.wav", argv[2]);
        write_wav(path, b, nb);
        snprintf(path, sizeof path, "%s/909GR.adpcm", argv[2]);
        write_raw(path, ea, (na + 1) / 2);
        snprintf(path, sizeof path, "%s/909FL.adpcm", argv[2]);
        write_raw(path, eb, (nb + 1) / 2);
        snprintf(path, sizeof path, "%s/pack.txt", argv[2]);
        m = fopen(path, "w");
        if (!m)
            return 1;
        fprintf(m, "# file samples bars name — full loops, not a shared prefix\n");
        fprintf(m, "909GR.adpcm %u %d 909 GR\n", na, BARS);
        fprintf(m, "909FL.adpcm %u %d 909 FL\n", nb, BARS);
        fclose(m);
    }
    free(a);
    free(b);
    free(ea);
    free(eb);
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only
 * Original portable implementation of SHA-256 and read-only capture bookkeeping.
 * No platform, transport, filesystem, allocator or flash-write dependency. */
#include "capture_core.h"
/* Freestanding target has no hosted string.h; bounded byte helpers avoid SDK libc. */
static void byte_copy(void *dst, const void *src, size_t n)
{
    uint8_t *d = dst; const uint8_t *s = src;
    while (n--) *d++ = *s++;
}
static void byte_fill(void *dst, int value, size_t n)
{
    uint8_t *d = dst;
    while (n--) *d++ = (uint8_t)value;
}
static int byte_diff(const void *a, const void *b, size_t n)
{
    const uint8_t *x = a, *y = b;
    while (n--) if (*x++ != *y++) return 1;
    return 0;
}

static uint32_t rr(uint32_t x, unsigned n) { return (x >> n) | (x << (32u - n)); }
static uint32_t be32(const uint8_t *p)
{ return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3]; }
static void put32(uint8_t *p, uint32_t x)
{ p[0]=(uint8_t)(x>>24); p[1]=(uint8_t)(x>>16); p[2]=(uint8_t)(x>>8); p[3]=(uint8_t)x; }
static void compress(struct mb_capture_hash *s)
{
    static const uint32_t k[64] = {
        0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
        0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
        0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
        0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
        0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
        0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
        0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
        0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2 };
    uint32_t w[64],a,b,c,d,e,f,g,h,t1,t2; unsigned i;
    for(i=0;i<16;i++) w[i]=be32(s->block+4*i);
    for(i=16;i<64;i++) {
        uint32_t x=w[i-15],y=w[i-2];
        w[i]=w[i-16]+(rr(x,7)^rr(x,18)^(x>>3))+w[i-7]+(rr(y,17)^rr(y,19)^(y>>10));
    }
    a=s->h[0];b=s->h[1];c=s->h[2];d=s->h[3];e=s->h[4];f=s->h[5];g=s->h[6];h=s->h[7];
    for(i=0;i<64;i++) {
        t1=h+(rr(e,6)^rr(e,11)^rr(e,25))+((e&f)^((~e)&g))+k[i]+w[i];
        t2=(rr(a,2)^rr(a,13)^rr(a,22))+((a&b)^(a&c)^(b&c));
        h=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2;
    }
    s->h[0]+=a;s->h[1]+=b;s->h[2]+=c;s->h[3]+=d;s->h[4]+=e;s->h[5]+=f;s->h[6]+=g;s->h[7]+=h;
}
static void hash_init(struct mb_capture_hash *s)
{
    static const uint32_t iv[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
        0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    byte_fill(s,0,sizeof *s);byte_copy(s->h,iv,sizeof iv);
}
static void hash_add(struct mb_capture_hash *s,const uint8_t *p,size_t n)
{
    s->bytes+=(uint64_t)n;
    while(n) {
        size_t k=64-s->used;if(k>n)k=n;
        byte_copy(s->block+s->used,p,k);s->used+=k;p+=k;n-=k;
        if(s->used==64){compress(s);s->used=0;}
    }
}
static void hash_end(struct mb_capture_hash *s,uint8_t out[32])
{
    uint64_t bits=s->bytes*8u;unsigned i;
    s->block[s->used++]=0x80;
    if(s->used>56){byte_fill(s->block+s->used,0,64-s->used);compress(s);s->used=0;}
    byte_fill(s->block+s->used,0,56-s->used);
    for(i=0;i<8;i++)s->block[63-i]=(uint8_t)(bits>>(8*i));
    compress(s);for(i=0;i<8;i++)put32(out+4*i,s->h[i]);
    byte_fill(s,0,sizeof *s);
}
int mb_capture_sha256(const uint8_t *data,size_t length,uint8_t output[32])
{
    struct mb_capture_hash s;
    if(!output || (!data && length))return MB_CAPTURE_ARGUMENT;
#if SIZE_MAX > (UINT64_MAX / 8u)
    if(length>UINT64_MAX/8u)return MB_CAPTURE_ARGUMENT;
#endif
    hash_init(&s);hash_add(&s,data,length);hash_end(&s,output);return MB_CAPTURE_OK;
}
static int nonzero(const uint8_t p[32])
{ unsigned i;uint8_t x=0;for(i=0;i<32;i++)x|=p[i];return x!=0; }
static int valid_binding(const struct mb_capture_binding *b)
{
    return b && (b->model==1 || b->model==2) && nonzero(b->unit) &&
        nonzero(b->session) && nonzero(b->challenge) && nonzero(b->selection);
}
static int same(const struct mb_capture_binding *a,const struct mb_capture_binding *b)
{
    return b && a->epoch==b->epoch && a->model==b->model &&
        !byte_diff(a->unit,b->unit,32) && !byte_diff(a->session,b->session,32) &&
        !byte_diff(a->challenge,b->challenge,32) && !byte_diff(a->selection,b->selection,32);
}
static int fail(struct mb_capture *c,int rc)
{ if(c){byte_fill(c,0,sizeof *c);c->state=MB_CAPTURE_INVALID;}return rc; }
int mb_capture_platform_supported(void){return 0;}
int mb_capture_start(struct mb_capture *c,const struct mb_capture_binding *b,
                     uint32_t facts,uint64_t now,uint64_t deadline)
{
    if(!c)return MB_CAPTURE_ARGUMENT;
    /* Do not discard another in-progress owner lease. */
    if(c->state!=MB_CAPTURE_EMPTY && c->state!=MB_CAPTURE_CANCELLED &&
       c->state!=MB_CAPTURE_INVALID)return MB_CAPTURE_STATE;
    byte_fill(c,0,sizeof *c);
    if(facts!=MB_CAPTURE_REQUIRED)return fail(c,MB_CAPTURE_UNSUPPORTED);
    if(!valid_binding(b) || deadline<=now)return fail(c,MB_CAPTURE_ARGUMENT);
    byte_copy(&c->binding,b,sizeof *b);c->last_now=now;c->deadline=deadline;c->state=MB_CAPTURE_STREAMING;
    hash_init(&c->full);hash_init(&c->head);return MB_CAPTURE_OK;
}
static int live(struct mb_capture *c,const struct mb_capture_binding *b,uint64_t now)
{
    if(!c)return MB_CAPTURE_ARGUMENT;
    if(c->state!=MB_CAPTURE_STREAMING && c->state!=MB_CAPTURE_COMPLETE_HELD &&
       c->state!=MB_CAPTURE_REVALIDATED_HELD)return fail(c,MB_CAPTURE_STATE);
    if(!same(&c->binding,b) || now<c->last_now || now>=c->deadline)return fail(c,MB_CAPTURE_STALE);
    c->last_now=now;return MB_CAPTURE_OK;
}
int mb_capture_chunk(struct mb_capture *c,const struct mb_capture_binding *b,
                     uint32_t offset,const uint8_t *data,uint32_t n,uint64_t now)
{
    int rc=live(c,b,now);uint32_t hn;
    if(rc)return rc;
    if(c->state!=MB_CAPTURE_STREAMING)return fail(c,MB_CAPTURE_STATE);
    if(!data || !n || n>MB_CAPTURE_CHUNK || offset!=c->next ||
       offset>MB_CAPTURE_SIZE || n>MB_CAPTURE_SIZE-offset)return fail(c,MB_CAPTURE_COVERAGE);
    hash_add(&c->full,data,n);
    if(offset<MB_CAPTURE_HEAD){hn=MB_CAPTURE_HEAD-offset;if(hn>n)hn=n;hash_add(&c->head,data,hn);}
    c->next+=n;return MB_CAPTURE_OK;
}
int mb_capture_finish(struct mb_capture *c,const struct mb_capture_binding *b,
                      const struct mb_capture_digests *target,uint64_t now,
                      struct mb_capture_digests *output)
{
    int rc=live(c,b,now);struct mb_capture_digests got;
    if(rc)return rc;
    if(!target || !output)return fail(c,MB_CAPTURE_ARGUMENT);
    if(c->state!=MB_CAPTURE_STREAMING)return fail(c,MB_CAPTURE_STATE);
    if(c->next!=MB_CAPTURE_SIZE)return fail(c,MB_CAPTURE_COVERAGE);
    hash_end(&c->full,got.full);hash_end(&c->head,got.head);
    if(byte_diff(got.full,target->full,32)||byte_diff(got.head,target->head,32))
        return fail(c,MB_CAPTURE_DIGEST_MISMATCH);
    byte_copy(&c->digests,&got,sizeof got);c->state=MB_CAPTURE_COMPLETE_HELD;byte_copy(output,&got,sizeof got);return MB_CAPTURE_OK;
}
int mb_capture_revalidate(struct mb_capture *c,const struct mb_capture_binding *b,
                          const uint8_t fresh[32],const struct mb_capture_digests *target,uint64_t now)
{
    int rc=live(c,b,now);if(rc)return rc;
    if(c->state!=MB_CAPTURE_COMPLETE_HELD)return fail(c,MB_CAPTURE_STATE);
    if(!fresh || !target)return fail(c,MB_CAPTURE_ARGUMENT);
    if(!nonzero(fresh)||!byte_diff(fresh,c->binding.challenge,32))return fail(c,MB_CAPTURE_REPLAY);
    if(byte_diff(target->full,c->digests.full,32)||byte_diff(target->head,c->digests.head,32))
        return fail(c,MB_CAPTURE_DIGEST_MISMATCH);
    c->state=MB_CAPTURE_REVALIDATED_HELD;return MB_CAPTURE_OK;
}
int mb_capture_evidence_current(struct mb_capture *c,const struct mb_capture_binding *b,uint64_t now)
{
    int rc=live(c,b,now);if(rc)return rc;
    if(c->state!=MB_CAPTURE_REVALIDATED_HELD)return fail(c,MB_CAPTURE_STATE);
    return MB_CAPTURE_OK;
}
void mb_capture_invalidate(struct mb_capture *c){(void)fail(c,MB_CAPTURE_STALE);}
int mb_capture_cancel(struct mb_capture *c,const struct mb_capture_binding *b)
{
    if(!c || !b)return MB_CAPTURE_ARGUMENT;
    if(!same(&c->binding,b))return MB_CAPTURE_FOREIGN_OWNER;
    byte_fill(c,0,sizeof *c);c->state=MB_CAPTURE_CANCELLED;return MB_CAPTURE_OK;
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Native host contract for production clip-key MIDI note ownership.

Extract ck_key_send and ck_voice unchanged from firmware/src/app/main_fm1.c,
including the actual ck_press call's status, then exercise the real functions
against deterministic overlapping key/chord outputs and a MIDI sink. The
ck_key_notes mock tests MIDI ownership, not the already-covered scale math.
"""
import argparse
import os
from pathlib import Path
import re
import subprocess
import tempfile


def function(src, name):
    match = re.search(r'\b(?:static\s+)?void\s+' + re.escape(name) + r'\s*\([^;]*?\)\s*\{', src)
    if match is None:
        raise RuntimeError(f'{name}: source window missing')
    p, level = match.start(), 0
    for i in range(match.end() - 1, len(src)):
        if src[i] == '{':
            level += 1
        elif src[i] == '}':
            level -= 1
            if not level:
                return src[p:i + 1]
    raise RuntimeError(f'{name}: unclosed source window')


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('source', nargs='?', default='firmware/src/app/main_fm1.c')
    ap.add_argument('--cc', default=os.environ.get('CC', 'cc'))
    args = ap.parse_args()
    src = Path(args.source).read_text(encoding='utf-8')
    press = function(src, 'ck_press')
    mark = re.search(r'\bck_key_send\(k,\s*(0x[0-9a-fA-F]+u)\s*\)', press)
    if mark is None:
        raise RuntimeError('ck_press direct note-on call missing')
    press_status = mark.group(1)
    send_src = function(src, 'ck_key_send')
    voice_src = function(src, 'ck_voice')
    live = 'static uint32_t ck_clip_live[4];' in src
    clip_helpers = (function(src, 'ck_clip_on') + '\n' + function(src, 'ck_clip_off')) if live else ''
    host = r'''
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CK_NKEY 37u
#define CK_MAXN 7u
#define CK_FN
#define CK_M_ARP 1u
#define CK_BIT(map, k) (((map)[(k) >> 5] >> ((k) & 31u)) & 1u)
typedef struct { uint32_t snd[2]; uint8_t ch, on, nk; } ck_state_t;
static ck_state_t ck;
#define CK_BASE ck_state_t *cp = &ck
static int on[128], off[128], balance[128], errors, checks;
static void ck_on(uint32_t n) {
    if (n >= 128u) abort();
    on[n]++; balance[n]++;
}
static void ck_send(uint32_t status, uint32_t n, uint32_t v) {
    (void)v;
    if ((status & 0xF0u) != 0x80u || n >= 128u) abort();
    off[n]++; balance[n]--;
    if (balance[n] < 0) errors++;
}
/* C/C# snap together to C in MAJOR NEAR; second pair shares two tones
 * between two chords. The upstream scale math is separately tested by
 * smk_clip_keys_test.c; this mock intentionally isolates note ownership. */
static uint32_t ck_key_notes(uint32_t k, uint8_t *out) {
    if (k <= 1u) { out[0] = 60; return 1; }
    if (k == 2u) { out[0] = 60; out[1] = 64; out[2] = 67; return 3; }
    if (k == 3u) { out[0] = 64; out[1] = 67; return 2; }
    out[0] = (uint8_t)(48 + k); return 1;
}
#define CHECK(test, name) do { checks++; if (!(test)) { \
  fprintf(stderr, "FAIL %s line %d\n", name, __LINE__); errors++; } } while(0)
static void reset(void) { memset(&ck, 0, sizeof ck); memset(on, 0, sizeof on); \
 memset(off, 0, sizeof off); memset(balance, 0, sizeof balance); errors = checks = 0; }
static void press(uint32_t k) { ck.snd[k >> 5] |= 1u << (k & 31u); ck_key_send(k, PRESS_STATUS); }
static void release(uint32_t k) { ck.snd[k >> 5] &= ~(1u << (k & 31u)); ck_key_send(k, 0x81u); }
static int suite(void) {
    int failures = 0;
    reset();
    press(0); press(1);
    CHECK(on[60] == 1 && balance[60] == 1, "overlapping snapped keys emit one NoteOn");
    release(0);
    CHECK(off[60] == 0 && balance[60] == 1, "releasing first keeps common voice");
    release(1);
    CHECK(on[60] == 1 && off[60] == 1 && balance[60] == 0, "last release balances snapped note");
    failures += errors;
    reset();
    press(1); press(0); release(1); release(0);
    CHECK(on[60] == 1 && off[60] == 1 && balance[60] == 0, "reverse press/release order");
    failures += errors;
    reset();
    press(0); press(1);
    ck_voice(0x80u); /* old pitch owner before a settings change */
    CHECK(off[60] == 1 && balance[60] == 0, "settings off unique per pitch");
    ck_voice(0x90u); /* new pitch owner after a settings change */
    CHECK(on[60] == 2 && balance[60] == 1, "settings on unique per pitch");
    release(0); release(1);
    CHECK(off[60] == 2 && balance[60] == 0, "setting revoice then key release balances");
    failures += errors;
    reset();
    press(2); press(3);
    CHECK(on[60] == 1 && on[64] == 1 && on[67] == 1, "chords with shared tones deduplicated");
    release(2); release(3);
    CHECK(balance[60] == 0 && balance[64] == 0 && balance[67] == 0, "shared chords all release");
    failures += errors;
    reset();
    press(4); press(5);
    CHECK(on[52] == 1 && on[53] == 1, "different notes still both play");
    release(4); release(5);
    CHECK(balance[52] == 0 && balance[53] == 0, "different notes release");
    failures += errors;
    reset();
    press(0); press(1); ck_voice(0x80u);
    CHECK(off[60] == 1 && balance[60] == 0, "bulk all-off does not duplicate NoteOff");
    failures += errors;
    printf("clip_key_overlap_test: %d failures (12 critical observations)\n", failures);
    return failures ? 1 : 0;
}
int main(void) { return suite(); }
'''
    body = host.replace('#define CK_FN', '#define CK_FN\n#define PRESS_STATUS ' + press_status)
    if live:
        body = body.replace('static ck_state_t ck;', 'static ck_state_t ck;\nstatic uint32_t ck_clip_live[4];')
        body = body.replace('memset(&ck, 0, sizeof ck);',
                            'memset(ck_clip_live, 0, sizeof ck_clip_live); memset(&ck, 0, sizeof ck);')
    body = body.replace('static void reset(void)', clip_helpers + '\n' + send_src + '\n' + voice_src + '\nstatic void reset(void)')
    with tempfile.TemporaryDirectory(prefix='x0x37-clip-overlap-') as td:
        cfile = Path(td, 'clip_overlap.c')
        exe = Path(td, 'clip_overlap')
        cfile.write_text(body, encoding='utf-8')
        opts = os.environ.get('CFLAGS', '-O2 -Wall -Wextra -Werror').split()
        print(f'compiler={args.cc} flags={opts} source={args.source} direct_press_status={press_status}', flush=True)
        comp = subprocess.run([args.cc, '-std=c99', *opts, str(cfile), '-o', str(exe)], check=False)
        if comp.returncode:
            return comp.returncode
        run = subprocess.run([str(exe)], check=False)
        return run.returncode


if __name__ == '__main__':
    raise SystemExit(main())

/* SPDX-License-Identifier: GPL-3.0-only */
#include "wobble.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
enum { N = 48000 };
static float a[N], b[N], c[N], d[N];
static void note(wobble_t *s, float *l, float *r, unsigned block)
{
    wobble_note_on(s, 48, 80);
    for (unsigned p = 0; p < N;) {
        if (p == 24000) wobble_note_off(s, 48);
        unsigned end = p < 24000 ? 24000 : N;
        unsigned n = end - p < block ? end - p : block;
        wobble_render(s, l+p, r+p, n); p += n;
    }
}
static void finite_buffer(unsigned n)
{
    for (unsigned i=0; i<n; ++i) {
        assert(isfinite(a[i]) && isfinite(b[i]));
        assert(fabsf(a[i]) < 4 && fabsf(b[i]) < 4);
    }
}
static void deterministic_blocks(void)
{
    wobble_t s;
    wobble_init(&s,48000); note(&s,c,d,256);
    for (unsigned block=1; block<=256; ++block) {
        wobble_init(&s,48000); note(&s,a,b,block);
        assert(memcmp(a,c,sizeof a)==0 && memcmp(b,d,sizeof b)==0);
    }
    note(&s,a,b,127);
    assert(memcmp(a,c,sizeof a)!=0); /* retained active phase, explicit history */
    wobble_reset(&s); note(&s,a,b,127);
    assert(memcmp(a,c,sizeof a)==0 && memcmp(b,d,sizeof b)==0);
    puts("PASS deterministic fresh/reset, active history, all block sizes 1..256");
}
static void pitch_tail_and_ownership(void)
{
    wobble_t s;
    wobble_init(&s,48000); wobble_set(&s,W_CUTOFF,1); note(&s,a,b,256);
    finite_buffer(N);
    for(unsigned i=0;i<N;++i) assert(a[i]==b[i]);
    double first=0,last=0; unsigned crossings=0;
    for(unsigned i=4801;i<19200;++i) if(a[i-1]<=0 && a[i]>0) {
        double t=i-1 + (double)(-a[i-1])/(a[i]-a[i-1]);
        if(!crossings)first=t; last=t; ++crossings;
    }
    assert(crossings>20);
    double hz=(crossings-1)*48000.0/(last-first);
    double cents=1200*log2(hz/(440*pow(2,-21.0/12)));
    printf("pitch_hz=%.8f pitch_error_cents=%.6f\n",hz,cents);
    assert(fabs(cents)<1.0);
    assert(!s.active && s.filter_low==0 && s.filter_band==0);
    for(unsigned i=26000;i<N;++i)assert(a[i]==0 && b[i]==0);
    wobble_note_on(&s,48,80); wobble_note_on(&s,55,80);
    wobble_note_off(&s,48); assert(s.gate);
    wobble_note_off(&s,55); assert(!s.gate);
    wobble_note_on(&s,48,80); wobble_set(&s,W_DAMPER,1);
    wobble_note_off(&s,48); assert(s.gate && s.deferred_off);
    wobble_set(&s,W_DAMPER,0); assert(!s.gate && !s.deferred_off);
    wobble_note_on(&s,48,80); wobble_all_notes_off(&s); assert(!s.gate);
    puts("PASS pitch, exact tail silence, mono, last-note ownership, damper cleanup");
}
static void modulation_null_and_stereo(void)
{
    wobble_t s;
    wobble_init(&s,48000); note(&s,c,d,256);
    wobble_init(&s,48000); wobble_set(&s,W_XMOD_DEPTH,.15f);
    wobble_set(&s,W_XMOD_WAVE,1); note(&s,a,b,256);
    assert(!memcmp(a,c,sizeof a));
    wobble_init(&s,48000); wobble_set(&s,W_STEREO,1); note(&s,a,b,256);
    double side=0;
    for(unsigned i=0;i<N;++i) {
        assert(fabsf((a[i]+b[i])*.5f-c[i])<1e-7f);
        side+=fabs(a[i]-b[i]);
    }
    assert(side>1);
    wobble_init(&s,48000); wobble_set(&s,W_XMOD_LEVEL,.7f);
    wobble_set(&s,W_XMOD_DEPTH,.15f); note(&s,a,b,256);
    assert(memcmp(a,c,sizeof a)!=0);
    puts("PASS mod-level0 control null, positive modulation, stereo and mono downmix");
}
static void sweeps(void)
{
    static const float rates[]={8000,44100,48000,192000};
    wobble_t s;
    for(unsigned sr=0;sr<4;++sr)for(unsigned note_i=0;note_i<3;++note_i) {
        wobble_init(&s,rates[sr]); wobble_note_on(&s,(uint8_t)(note_i*63),127);
        for(unsigned p=0;p<W_PARAMETER_COUNT;++p)for(unsigned step=0;step<=32;++step) {
            assert(wobble_set(&s,p,step/32.0f));
            wobble_render(&s,a,b,256); finite_buffer(256);
        }
        for(unsigned j=0;j<W_PARAMETER_COUNT;++j) {
            if(j>=W_ATTACK && j<=W_RELEASE) continue;
            wobble_set(&s,j,1);
        }
        wobble_render(&s,a,b,256); finite_buffer(256);
        wobble_all_notes_off(&s);
        for(unsigned j=0;j<4800;++j) wobble_render(&s,a,b,256);
        assert(!s.active);
    }
    wobble_init(&s,NAN); assert(s.sample_rate==48000);
    assert(!wobble_set(&s,W_CUTOFF,NAN));
    assert(!wobble_set(&s,W_CUTOFF,INFINITY));
    assert(!wobble_set(&s,W_PARAMETER_COUNT,0));
    assert(wobble_set(&s,W_CUTOFF,-1) && s.p[W_CUTOFF]==0);
    assert(wobble_set(&s,W_CUTOFF,2) && s.p[W_CUTOFF]==1);
    puts("PASS finite bounded extreme/swept controls at 8/44.1/48/192kHz, input validation");
}
static void control_sensitivity_and_glide(void)
{
    wobble_t s;
    static const unsigned controls[]={W_CARRIER_WAVE,W_SUB_LEVEL,W_CARRIER_PITCH,
        W_XMOD_LEVEL,W_CUTOFF,W_CRUSH,W_WOBBLE_DEPTH,W_STEREO,W_PITCH_BEND};
    static const float values[]={1,.7f,.75f,.7f,.2f,.6f,.7f,.8f,.75f};
    wobble_init(&s,48000); note(&s,c,d,256);
    for(unsigned i=0;i<sizeof controls/sizeof controls[0];++i) {
        wobble_init(&s,48000); wobble_set(&s,controls[i],values[i]);
        note(&s,a,b,256);
        assert(memcmp(a,c,sizeof a)!=0 || memcmp(b,d,sizeof b)!=0);
    }
    wobble_init(&s,48000); wobble_set(&s,W_XMOD_LEVEL,.7f); note(&s,c,d,256);
    wobble_init(&s,48000); wobble_set(&s,W_XMOD_LEVEL,.7f);
    wobble_set(&s,W_XMOD_WAVE,1); note(&s,a,b,256); assert(memcmp(a,c,sizeof a));
    wobble_init(&s,48000); wobble_set(&s,W_XMOD_LEVEL,.7f);
    wobble_set(&s,W_XMOD_TUNE,.75f); note(&s,a,b,256); assert(memcmp(a,c,sizeof a));
    wobble_init(&s,48000); wobble_set(&s,W_WOBBLE_DEPTH,.7f); note(&s,c,d,256);
    wobble_init(&s,48000); wobble_set(&s,W_WOBBLE_DEPTH,.7f);
    wobble_set(&s,W_WOBBLE_SHAPE,1); note(&s,a,b,256); assert(memcmp(a,c,sizeof a));
    wobble_init(&s,48000); wobble_set(&s,W_WOBBLE_DEPTH,.7f);
    wobble_set(&s,W_WOBBLE_RATE,1); note(&s,a,b,256); assert(memcmp(a,c,sizeof a));
    wobble_init(&s,48000); wobble_set(&s,W_GLIDE,1);
    wobble_note_on(&s,48,80); wobble_render(&s,a,b,256); float previous=s.hz;
    wobble_note_on(&s,60,80); assert(s.hz==previous && s.hz<s.target_hz);
    wobble_render(&s,a,b,256); assert(s.hz>previous && s.hz<s.target_hz);
    previous=s.hz;
    wobble_set(&s,W_GLIDE,0); wobble_render(&s,a,b,1);
    assert(s.hz==s.target_hz && s.hz>previous);
    wobble_reset(&s); wobble_set(&s,W_OUTPUT,0); note(&s,a,b,256);
    for(unsigned i=0;i<N;++i)assert(a[i]==0 && b[i]==0);
    puts("PASS control sensitivity, zero output, monotonic glide and immediate no-glide");
}
static void amp_adsr_extension(void)
{
    wobble_t s;
