    }
    double elapsed=(double)(clock()-start)/CLOCKS_PER_SEC;
    printf("host_benchmark_frames=%u cpu_seconds=%.6f cpu_seconds_per_audio_second=%.6f checksum=%.9f\n",
           frames,elapsed,elapsed/10,checksum);
}
