/* SPDX-License-Identifier: GPL-3.0-only */
/* The parts of the Bluetooth MIDI glue (src/ble.c) that touch no hardware, so the host tests
 * (tests/ble_test.c) compile them as they are:
 *   ble_img_check()    is the flash block a controller image this app can start?
 *   ble_usb_of_msg()   a BLE-MIDI message as a USB-MIDI event packet (the queue usb.c reads)
 *   ble_msg_of_usb()   a USB-MIDI event packet as the bytes of one MIDI message
 *   ble_addr_of()      the random static address and the name from the factory record
 *   ble_guard_*()      the start guard: a controller start that failed, crashed or reset the unit
 *                      is not tried again at the next power-on (STATUS FAILED, BEHAVIOR.md BLE-12) */
#pragma once
#include <stdint.h>
#include "x0x_ble_abi.h"
#include "ble_midi_host.h"

enum { BLE_IMG_OK = 0, BLE_IMG_NONE = 1, BLE_IMG_BAD = 2 };

/* img: the block as the CPU reads it (XIP), size bytes of it readable */
static int ble_img_check(const uint8_t *img, uint32_t size, uint32_t xip_base)
{
    const xb_header_t *h = (const xb_header_t *)(const void *)img;
    static const uint8_t zero4[4] = {0, 0, 0, 0};
    uint32_t crc, end;
    if (h->magic != XB_HDR_MAGIC)
        return BLE_IMG_NONE;                    /* an empty block (0xFF) or anything else */
    if (h->hdr_version != XB_HDR_VERSION || h->hdr_size != sizeof(xb_header_t) || h->abi != XB_ABI)
        return BLE_IMG_BAD;
    if (h->image_size < sizeof(xb_header_t) || h->image_size > size)
        return BLE_IMG_BAD;
    crc = xb_crc32(0, img, 16u);
    crc = xb_crc32(crc, zero4, 4u);
    crc = xb_crc32(crc, img + 20u, h->image_size - 20u);
    if (crc != h->crc32)
        return BLE_IMG_BAD;
    end = xip_base + h->image_size;
    if (h->init < xip_base + sizeof(xb_header_t) || h->init >= end ||
        h->poll < xip_base + sizeof(xb_header_t) || h->poll >= end)
        return BLE_IMG_BAD;
    if (h->ram_lo < XB_RAM_LO || h->ram_hi > XB_RAM_HI || h->ram_lo >= h->ram_hi)
        return BLE_IMG_BAD;
    if (h->isr_stack_lo < h->ram_lo || h->isr_stack_hi > h->ram_hi || h->isr_stack_lo >= h->isr_stack_hi ||
        (h->isr_stack_hi & 7u))
        return BLE_IMG_BAD;
    /* never an interrupt X0X uses on core 0: the exception, ALNK0, SPI1, UART1, SARADC, SPI2, 62, TIMER5 */
    if ((h->irq_lo & ((1u << 1) | (1u << 11) | (1u << 16) | (1u << 20) | (1u << 24))) ||
        (h->irq_hi & ((1u << (37 - 32)) | (1u << (62 - 32)) | (1u << (63 - 32)))))
        return BLE_IMG_BAD;
    return BLE_IMG_OK;
}

/* a BLE-MIDI message as a USB-MIDI event packet, cable 0 (0 = none) */
static uint32_t ble_usb_of_msg(const bleh_msg_t *m)
{
    uint32_t st = m->b[0], cin;
    if (st < 0x80u)
        return 0;
    if (st < 0xF0u)
        cin = st >> 4;                          /* 8..E: the channel messages */
    else if (st >= 0xF8u || st == 0xF6u)
        cin = st == 0xF6u ? 5u : 0xFu;          /* one byte */
    else if (st == 0xF1u || st == 0xF3u)
        cin = 2u;
    else if (st == 0xF2u)
        cin = 3u;
    else
        return 0;                               /* F0 F7 (SysEx comes another way), F4 F5 */
    return cin | st << 8 | (uint32_t)m->b[1] << 16 | (uint32_t)m->b[2] << 24;
}

/* a USB-MIDI event packet as one MIDI message: its length (0 = not one BLE-MIDI sends this way) */
static uint32_t ble_msg_of_usb(uint32_t pkt, uint8_t b[3])
{
    uint32_t cin = pkt & 0xFu, st = (pkt >> 8) & 0xFFu, n;
    b[0] = (uint8_t)st;
    b[1] = (uint8_t)((pkt >> 16) & 0x7Fu);
    b[2] = (uint8_t)((pkt >> 24) & 0x7Fu);
    if (cin >= 8u) {
        if (cin == 0xFu)
            return st >= 0xF8u ? 1u : 0u;       /* a single byte: real time only */
        if ((st >> 4) != cin)
            return 0;
        n = (cin == 0xCu || cin == 0xDu) ? 2u : 3u;
    } else if (cin == 2u && (st == 0xF1u || st == 0xF3u)) {
        n = 2u;
    } else if (cin == 3u && st == 0xF2u) {
        n = 3u;
    } else if (cin == 5u && st == 0xF6u) {
        n = 1u;
    } else {
        return 0;                               /* SysEx and anything else: not mirrored */
    }
    return n;
}

/* the address and the name "X0X-XXXX" from a factory record (the same on every boot of a unit,
 * different between units): a random static address, top two bits 11 */
static void ble_addr_of(const uint8_t *rec, uint32_t n, uint8_t addr[6], char name[9])
{
    /* Same 16 digits ui.c and main_fm1.c already index. One literal in this TU. */
    uint32_t a = xb_crc32(0, rec, n), b = xb_crc32(0x5A5A5A5Au, rec, n);
    addr[0] = (uint8_t)a;
    addr[1] = (uint8_t)(a >> 8);
    addr[2] = (uint8_t)(a >> 16);
    addr[3] = (uint8_t)(a >> 24);
    addr[4] = (uint8_t)b;
    addr[5] = (uint8_t)((b >> 8) | 0xC0u);
    name[0] = 'X'; name[1] = '0'; name[2] = 'X'; name[3] = '-';
    name[4] = "0123456789ABCDEF"[addr[1] >> 4]; name[5] = "0123456789ABCDEF"[addr[1] & 15u];
    name[6] = "0123456789ABCDEF"[addr[0] >> 4]; name[7] = "0123456789ABCDEF"[addr[0] & 15u];
    name[8] = 0;
}

/* ---- the start guard (src/ble.c keeps it in .noinit: it survives a reset, not a power-off) ----
 * Before the controller's init the app sets trying. A failed start (it did not come back, a wrong
 * job, not READY) sets blocked at once. A start that resets or freezes the unit leaves trying set:
 * the next boot sees it and sets blocked. While blocked, the controller does not start (STATUS
 * FAILED). BLUETOOTH OFF in GLO clears blocked: the next power-on tries again. trying ends when the
 * controller has run BLE_GUARD_OK_MS after its start. */
#define BLE_GUARD_MAGIC 0x44524742u              /* "BGRD" */
#define BLE_GUARD_OK_MS 10000u
enum { BLE_WHY_NONE = 0, BLE_WHY_TIMEOUT = 1, BLE_WHY_WRONG_JOB = 2, BLE_WHY_NOT_READY = 3, BLE_WHY_RESET = 4,
       BLE_WHY_NO_TICK = 5 };
typedef struct {
    uint32_t magic, trying, blocked, why, fails;
    uint32_t start_ms, init_ms, mb_state, mb_err;  /* the last start: its time, how long init took, the mailbox */
    uint32_t dbg[6];                               /* the image's own record of the last start (xb_mbox_t dbg) */
    uint32_t reset;                                /* BLE_WHY_RESET: P3 reset source | RST_SRC << 8 of that reset */
    uint32_t sink_n, sink_at, sink_val;            /* the RAM sink after the start: words changed, the first */
    uint32_t wait_end;                             /* fm1_c1_wait_end of the start (fm1_cpu1.h) */
    uint32_t xosc_pre, xosc_post;                  /* WLA_CON12 (crystal trim) before the start and after init */
    uint32_t wait_ms;                              /* fm1_c1_wait_ms: core 0's last look in the wait, ms */
    uint32_t seen[4];                              /* the image's dbg[0..3] at that look (fm1_c1_wait_seen) */
    uint32_t code_bad, code_sum;                   /* RAM code 0x01C00400..XB_RAM_LO changed: 0xBAD00000 | ms, the sum */
} ble_guard_t;

/* power-on: 1 = start the controller now */
static int ble_guard_boot(ble_guard_t *g, int img_ok, int on)
{
    uint32_t i;
    if (g->magic != BLE_GUARD_MAGIC) {
        uint8_t *z = (uint8_t *)g;
        for (i = 0; i < sizeof *g; i++)
            z[i] = 0;
        g->magic = BLE_GUARD_MAGIC;
    }
    if (g->trying) {                             /* the last start did not finish: a reset or a hang */
        g->trying = 0;
        g->blocked = 1;
        g->why = BLE_WHY_RESET;
        g->fails++;
    }
    if (!img_ok || !on || g->blocked)
        return 0;
    g->trying = 1;
    return 1;
}
/* after the controller's init: rc (0 from ble_start; -1 timeout, -2 wrong job, -3 no tick),
 * ready = the mailbox says READY */
static void ble_guard_started(ble_guard_t *g, int rc, int ready)
{
    if (rc == 0 && ready)
        return;                                  /* trying stays until ble_guard_ok */
    g->trying = 0;
    g->blocked = 1;
    g->why = rc == -1 ? BLE_WHY_TIMEOUT : rc == -3 ? BLE_WHY_NO_TICK : rc ? BLE_WHY_WRONG_JOB : BLE_WHY_NOT_READY;
    g->fails++;
}
/* the controller ran long enough: the start is good */
static void ble_guard_ok(ble_guard_t *g)
{
    g->trying = 0;
    g->fails = 0;
}
/* BLUETOOTH set OFF in GLO: the next power-on tries again */
static void ble_guard_user_off(ble_guard_t *g)
{
    g->blocked = 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Full store ordering on the AC79 (shared caches; see fm1_cpu1.h). */
#pragma once

static inline void fm1_data_sync(void)
{
    __asm__ volatile("csync" ::: "memory");
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Exercise real generator output admission, including buffered close failures."""
import os
from pathlib import Path
import shlex
import subprocess
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[2]


class BuiltinBreakOutput(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.temp = tempfile.TemporaryDirectory(prefix="x0x-break-output-")
        cls.root = Path(cls.temp.name)
        gen = cls.root / "gen"
        gen.mkdir()
        subprocess.run(["python3", str(ROOT / "tools/gen_drum_samples.py"),
                        str(gen / "x0x_drum_samples.h")], check=True,
                       stdout=subprocess.DEVNULL)
        cls.binary = cls.root / "generator"
        subprocess.run(shlex.split(os.environ.get("CC", "cc")) + [
            "-O2", "-ffp-contract=off", "-w", "-I" + str(ROOT / "firmware/src"),
            "-I" + str(gen), "-o", str(cls.binary),
            str(ROOT / "tools/gen_builtin_break.c"),
            str(ROOT / "firmware/src/dsp/drum909.c"),
            str(ROOT / "firmware/src/dsp/x0x_param.c"), "-lm"], check=True)

    @classmethod
    def tearDownClass(cls):
        cls.temp.cleanup()

    def invoke(self, *args):
        return subprocess.run([str(self.binary), *map(str, args)],
                              capture_output=True, text=True)

    def assert_failure(self, result):
        self.assertNotEqual(result.returncode, 0)
        self.assertNotIn("builtin break: A", result.stdout)

    def test_success_bytes_are_deterministic(self):
        dirs = [self.root / "normal-a", self.root / "normal-b"]
        for directory in dirs:
            directory.mkdir()
            result = self.invoke(directory / "bank.h", directory)
            self.assertEqual(result.returncode, 0, result.stderr)
            self.assertIn("builtin break: A", result.stdout)
        names = ["bank.h", "909GR.wav", "909FL.wav", "909GR.adpcm",
                 "909FL.adpcm", "pack.txt"]
        for name in names:
            self.assertEqual((dirs[0] / name).read_bytes(), (dirs[1] / name).read_bytes())
            self.assertGreater((dirs[0] / name).stat().st_size, 0)

    def test_missing_header_parent(self):
        self.assert_failure(self.invoke(self.root / "missing" / "bank.h"))

    def test_missing_export_directory(self):
        self.assert_failure(self.invoke(self.root / "missing-export.h", self.root / "absent"))

    def test_export_path_too_long(self):
        self.assert_failure(self.invoke(self.root / "long-export.h", "x" * 512))

    def test_header_write_failure(self):
        if not Path("/dev/full").exists():
            self.fail("/dev/full unavailable: required output-failure proof cannot run")
        self.assert_failure(self.invoke("/dev/full"))

    def test_each_export_write_and_open_failure(self):
        if not Path("/dev/full").exists():
            self.fail("/dev/full unavailable: required output-failure proof cannot run")
        for name in ["909GR.wav", "909FL.wav", "909GR.adpcm", "909FL.adpcm", "pack.txt"]:
            for failure in ["write", "open"]:
                with self.subTest(name=name, failure=failure):
                    with tempfile.TemporaryDirectory(dir=self.root) as tmp:
                        directory = Path(tmp)
                        target = directory / name
                        if failure == "write":
                            target.symlink_to("/dev/full")
                        else:
                            target.mkdir()
                        self.assert_failure(self.invoke(directory / "bank.h", directory))


if __name__ == "__main__":
    unittest.main()

/* SPDX-License-Identifier: GPL-3.0-only */
/* The master compressor: bypass is exact, the static curve, attack / release times,
 * makeup, parallel mix, and the kick-keyed PUMP. */
#include <math.h>
#include <stdio.h>
#include <string.h>
#include "../../firmware/src/dsp/master.h"

static int fails;
#define CHECK(c, ...) do { if (!(c)) { fails++; printf("  FAIL: "); printf(__VA_ARGS__); printf("\n"); } else { printf("  ok   "); printf(__VA_ARGS__); printf("\n"); } } while (0)
#define N 44100

static float buf[N * 2];
static master_t M;

static void setup(int thr, int ratio, int att, int rel)
{
    master_init(&M);
    master_set(&M, MST_LIMIT, 0);
    master_set(&M, MST_MODE, 0);
    master_set(&M, MST_THRESH, thr);
    master_set(&M, MST_RATIO, ratio);
    master_set(&M, MST_ATTACK, att);
    master_set(&M, MST_RELEASE, rel);
}

static void sine(float *x, int n, float db, int start)
{
    float a = powf(10.0f, db / 20.0f);
    int i;
    for (i = 0; i < n; i++)
        x[i] = a * sinf(2.0f * 3.14159265f * 1000.0f * (float)(i + start) / 44100.0f);
}

static void run(float *x, int n)
{
    int i;
    for (i = 0; i < n; i += 256)
        master_process(&M, x + i, n - i < 256 ? n - i : 256, 1.0f);
}

static float peak_db(const float *x, int n)
{
    float p = 0;
    int i;
    for (i = 0; i < n; i++)
        if (fabsf(x[i]) > p)
            p = fabsf(x[i]);
    return 20.0f * log10f(p + 1e-12f);
}

int main(void)
{
    int i;
    float ref[N];
    /* 1. bypass: ratio 1:1, PUMP 0, filter off, limiter off: the samples, exactly */
    setup(95, 0, 60, 60);
    sine(buf, N, -3.0f, 0);
    memcpy(ref, buf, sizeof ref);
    run(buf, N);
    CHECK(!memcmp(ref, buf, sizeof ref), "bypass at 1:1 with PUMP 0 is sample-exact");

    /* 2. static curve: -6 dBFS sine, threshold -24 dB, 4:1 -> peak at -24 + 18/4 = -19.5 dB */
    {
        int thr = (int)lroundf((-24.0f + 48.0f) * 127.0f / 48.0f);
        setup(thr, 4, 40, 90);
        sine(buf, 2 * N, -6.0f, 0);
        run(buf, 2 * N);
        float out = peak_db(buf + N, N);
        CHECK(fabsf(out - (-19.5f)) < 1.0f, "4:1 above a -24 dB threshold: -6 dB in -> %.2f dB out (want -19.5)", out);
        /* below the threshold (and below the knee): untouched */
        setup(thr, 4, 40, 90);
        sine(buf, N, -36.0f, 0);
        memcpy(ref, buf, sizeof ref);
        run(buf, N);
        CHECK(fabsf(peak_db(buf, N) - peak_db(ref, N)) < 0.01f, "-36 dB in, under the threshold: unchanged");
        /* INF: a limiter at the threshold (+ the knee's half) */
        setup(thr, 9, 40, 90);
        sine(buf, 2 * N, -6.0f, 0);
        run(buf, 2 * N);
        out = peak_db(buf + N, N);
        CHECK(out < -23.0f && out > -25.5f, "INF ratio holds -6 dB in to %.2f dB (threshold -24)", out);
    }

    /* 3. attack: a step from -40 to -6 dB; the gain reduction reaches 63% of its final value
     *    after about the attack time */
    {
        int thr = (int)lroundf(24.0f * 127.0f / 48.0f), att = 100;      /* -24 dB; attack pot 100 */
        float t_ms = 0.1f * powf(2.0f, 100.0f * 9.966f / 127.0f), final_gr = 0, hit = -1;
        setup(thr, 9, att, 127);
        for (i = 0; i < N; i++)
            buf[i] = 0.5f;                                               /* DC at -6 dB: |x| constant */
        run(buf, 64);
        final_gr = 18.0f;
        setup(thr, 9, att, 127);
        for (i = 0; i < N; i++) {
            float x = 0.5f;
            master_process(&M, &x, 1, 1.0f);
            if (hit < 0 && M.gr >= 0.632f * final_gr)
                hit = (float)i * 1000.0f / 44100.0f;
        }
        CHECK(hit > 0.7f * t_ms && hit < 1.3f * t_ms, "attack: 63%% of the reduction after %.1f ms (attack %.1f ms)", hit, t_ms);
    }

    /* 4. makeup and mix */
    {
        int thr = (int)lroundf(24.0f * 127.0f / 48.0f);
        float wet, half;
        setup(thr, 4, 40, 90);
        master_set(&M, MST_MAKEUP, 64);                                  /* +12.1 dB (24 dB would clip) */
        sine(buf, 2 * N, -6.0f, 0);
        run(buf, 2 * N);
        wet = peak_db(buf + N, N);
        CHECK(fabsf(wet - (-19.5f + 24.0f * 64.0f / 127.0f)) < 1.0f, "makeup +12 dB: %.2f dB (want -7.4)", wet);
        setup(thr, 4, 40, 90);
        master_set(&M, MST_MIX, 64);                                     /* about half wet */
        sine(buf, 2 * N, -6.0f, 0);
        run(buf, 2 * N);
        half = peak_db(buf + N, N);
        CHECK(half > -12.0f && half < -6.5f, "parallel mix 50%%: %.2f dB, between wet -19.5 and dry -6", half);
    }

    /* 5. PUMP: a kick ducks the mix by its depth, easing in over ~12 ms, then swells back */
    {
        float before, dip, later;
        setup(127, 0, 60, 60);                                           /* ratio 1:1: PUMP alone */
        master_set(&M, MST_PUMP, 64);                                    /* ~12 dB */
        master_set(&M, MST_PUMPSRC, PUMP_909);
        sine(buf, N, -6.0f, 0);
        run(buf, 4410);
        before = peak_db(buf + 2205, 2205);
        master_key(&M, 1, 1.0f);                                         /* an 808 kick: not the source */
        sine(buf, 441, -6.0f, 4410);
        run(buf, 441);
        CHECK(fabsf(peak_db(buf + 220, 220) - before) < 0.1f, "PUMP keyed by 909 ignores an 808 kick");
        master_key(&M, 0, 1.0f);
        sine(buf, N, -6.0f, 4851);
        run(buf, N);
        dip = peak_db(buf + 1940, 110);                                  /* 44 - 46.5 ms after the kick */
        later = peak_db(buf + 40000, 1000);                              /* ~0.9 s later */
        CHECK(before - peak_db(buf + 132, 44) < 5.0f,
              "... it eases in: %.1f dB down 3-4 ms after the kick (a 3 ms rise, 8 dB, was a click)",
              before - peak_db(buf + 132, 44));
        CHECK(before - dip > 9.0f && before - dip < 14.0f, "a 909 kick ducks %.1f dB (depth 12) by 45 ms", before - dip);
        CHECK(before - later < 0.5f, "... and the mix has swelled back after the release (%.2f dB down)", before - later);
    }
    /* 6. the limiter: a burst 6 dB over its ceiling comes out under it, and the gain eases in over
     *    the look-ahead (it used to halve the distance each sample: a ~1 dB step, a click) */
    {
        float step = 0.0f, prev = 1.0f, pk = 0.0f;
        setup(127, 0, 60, 60);
        master_set(&M, MST_LIMIT, 1);
        for (i = 0; i < N; i++) {
            float x = i < 4410 ? 0.3f * sinf(2.0f * 3.14159265f * 60.0f * (float)i / 44100.0f)        /* a kick: */
                               : 1.6f * cosf(2.0f * 3.14159265f * 60.0f * (float)(i - 4410) / 44100.0f);   /* at its peak at once */
            float d;
            master_process(&M, &x, 1, 1.0f);
            d = fabsf(20.0f * log10f(M.gain) - 20.0f * log10f(prev));
            prev = M.gain;
            if (d > step)
                step = d;
            if (i > 4410 + 2 * MST_LA && fabsf(x) > pk)
                pk = fabsf(x);
        }
        CHECK(pk < 0.9f, "limiter: a 60 Hz burst at 1.6, from its peak, comes out at %.2f (ceiling 0.8, soft above 0.89)", pk);
        CHECK(step < 0.5f, "limiter: the gain moves at most %.2f dB a sample", step);
    }
    /* 7. Bypassing the limiter must not replay stale look-ahead audio when re-enabled. */
    for (int stereo = 0; stereo <= 1; stereo++) {
        float l[MST_LA * 2], r[MST_LA * 2], peak = 0.0f;
        master_init(&M);
        /* Prime the look-ahead ring with an audible signal. */
        for (i = 0; i < MST_LA * 2; ++i)
            l[i] = r[i] = 0.5f;
        if (stereo)
            master_process_st(&M, l, r, MST_LA * 2, 1.0f);
        else
            master_process(&M, l, MST_LA * 2, 1.0f);
        master_set(&M, MST_LIMIT, 0);
        for (i = 0; i < MST_LA * 2; ++i)
            l[i] = r[i] = 0.0f;
        if (stereo)
            master_process_st(&M, l, r, MST_LA * 2, 1.0f);
        else
            master_process(&M, l, MST_LA * 2, 1.0f);
        master_set(&M, MST_LIMIT, 1);
        for (i = 0; i < MST_LA * 2; ++i)
            l[i] = r[i] = 0.0f;
        if (stereo)
            master_process_st(&M, l, r, MST_LA * 2, 1.0f);
        else
            master_process(&M, l, MST_LA * 2, 1.0f);
        for (i = 0; i < MST_LA * 2; ++i) {
            if (fabsf(l[i]) > peak) peak = fabsf(l[i]);
            if (stereo && fabsf(r[i]) > peak) peak = fabsf(r[i]);
        }
        CHECK(peak == 0.0f, "limiter OFF->ON (%s): stale look-ahead audio peak %.6f (want silence)",
              stereo ? "stereo" : "mono", peak);
        /* A fresh signal still emerges after the normal look-ahead, and assigning
         * the already enabled value must not reset an active ring. */
        for (i = 0; i < MST_LA * 2; ++i)
            l[i] = r[i] = 0.125f;
        if (stereo)
            master_process_st(&M, l, r, MST_LA * 2, 1.0f);
        else
            master_process(&M, l, MST_LA * 2, 1.0f);
        CHECK(fabsf(l[MST_LA * 2 - 1] - 0.125f) < 0.00001f &&
              (!stereo || fabsf(r[MST_LA * 2 - 1] - 0.125f) < 0.00001f),
              "limiter OFF->ON (%s): fresh signal passes after look-ahead", stereo ? "stereo" : "mono");
        master_set(&M, MST_LIMIT, 1);                 /* unchanged setting: do not reset */
        l[0] = r[0] = 0.0f;
        if (stereo)
            master_process_st(&M, l, r, 1, 1.0f);
        else
            master_process(&M, l, 1, 1.0f);
        CHECK(fabsf(l[0] - 0.125f) < 0.00001f &&
              (!stereo || fabsf(r[0] - 0.125f) < 0.00001f),
              "limiter unchanged (%s): live look-ahead remains intact", stereo ? "stereo" : "mono");
    }
    printf("master: %s\n", fails ? "FAIL" : "ok");
    return fails != 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* A small LZ77 for the project's patterns, song and motion (project.c), which are mostly empty
 * steps and repeats: 64 steps x 32 patterns plus the lanes are ~30 KB raw and a few KB packed.
 *
 * Stream: a control byte c, then
 *   c < 0x80   c + 1 literal bytes follow (1..128);
 *   c >= 0x80  a match of (c & 0x7F) + LZ_MIN bytes (3..130), then its distance - 1 as a u16
 *              (little endian), copied a byte at a time: a distance shorter than the length
 *              repeats, so a run of one byte is a literal and a match at distance 1.
 *
 * The compressor writes through a sink (a run of bytes at a time), so its output can go to the
 * flash objects one chunk at a time, and reads its input in place. It remembers the last position
 * of each 3-byte hash (lz_head, 4 KB) and tries the byte before too (runs). The decompressor reads
 * a byte at a time from a source and writes into place. No allocation; inputs under 64 KB. */
#include <stdint.h>

#define LZ_MIN 3u
#define LZ_MAXLEN (0x7Fu + LZ_MIN)
#define LZ_MAXLIT 128u
#define LZ_HBITS 11
#define LZ_NONE 0xFFFFu

typedef struct {
    int (*put)(void *ctx, const uint8_t *p, uint32_t n);   /* 0 = taken; else the compression stops */
    void *ctx;
} lz_sink_t;

typedef struct {
    int (*get)(void *ctx);                                  /* the next byte, -1 = none left */
    void *ctx;
} lz_src_t;

#ifdef LZ_SCRATCH                      /* the app: a main-loop scratch that it shares (4 KiB) */
#define lz_head LZ_SCRATCH
#else
static uint16_t lz_head[1u << LZ_HBITS];
#endif

static uint32_t lz_hash(const uint8_t *p)
{
    return (((uint32_t)p[0] << 16 | (uint32_t)p[1] << 8 | p[2]) * 2654435761u) >> (32 - LZ_HBITS);
}

static uint32_t lz_match_len(const uint8_t *in, uint32_t n, uint32_t cand, uint32_t i)
{
    uint32_t len = 0;
    while (len < LZ_MAXLEN && i + len < n && in[cand + len] == in[i + len])
        len++;
    return len;
}

static int lz_literals(lz_sink_t *o, const uint8_t *p, uint32_t n)
{
    while (n) {
        uint32_t k = n > LZ_MAXLIT ? LZ_MAXLIT : n;
        uint8_t c = (uint8_t)(k - 1u);
        if (o->put(o->ctx, &c, 1) || o->put(o->ctx, p, k))
            return -1;
        p += k;
        n -= k;
    }
    return 0;
}

/* 0 = all of in[0..n) went to the sink; -1 = the sink refused (or n is too big) */
static int lz_compress(const uint8_t *in, uint32_t n, lz_sink_t *o)
{
    uint32_t i = 0, lit = 0, k;
    if (n >= LZ_NONE)
        return -1;
    for (k = 0; k < (1u << LZ_HBITS); k++)
        lz_head[k] = LZ_NONE;
    while (i < n) {
        uint32_t best = 0, dist = 0;
        if (i + LZ_MIN <= n) {
            uint32_t h = lz_hash(in + i), c = lz_head[h], len;
            lz_head[h] = (uint16_t)i;
            if (c != LZ_NONE && (len = lz_match_len(in, n, c, i)) > best) {
                best = len;
                dist = i - c;
            }
            if (i && (len = lz_match_len(in, n, i - 1u, i)) > best) {   /* a run */
                best = len;
                dist = 1;
            }
        }
        if (best < LZ_MIN) {
            i++;
            continue;
        }
        if (lz_literals(o, in + lit, i - lit))
            return -1;
        {
            uint8_t m[3] = {(uint8_t)(0x80u | (best - LZ_MIN)), (uint8_t)(dist - 1u), (uint8_t)((dist - 1u) >> 8)};
            if (o->put(o->ctx, m, 3))
                return -1;
        }
        for (k = 1; k < best && i + k + LZ_MIN <= n; k++)       /* the positions inside the match */
            lz_head[lz_hash(in + i + k)] = (uint16_t)(i + k);
        i += best;
        lit = i;
    }
    return lz_literals(o, in + lit, i - lit);
}

/* 0 = exactly n bytes came out; -1 = the stream ended early or does not fit */
static int lz_decompress(lz_src_t *s, uint8_t *out, uint32_t n)
{
    uint32_t w = 0;
    while (w < n) {
        int c = s->get(s->ctx), b;
        uint32_t len, dist;
        if (c < 0)
            return -1;
        if (c < 0x80) {
            for (len = (uint32_t)c + 1u; len; len--) {
                if (w >= n || (b = s->get(s->ctx)) < 0)
                    return -1;
                out[w++] = (uint8_t)b;
            }
            continue;
        }
        len = ((uint32_t)c & 0x7Fu) + LZ_MIN;
        if ((b = s->get(s->ctx)) < 0)
            return -1;
        dist = (uint32_t)b;
        if ((b = s->get(s->ctx)) < 0)
            return -1;
        dist |= (uint32_t)b << 8;
        dist++;
        if (dist > w || len > n - w)
            return -1;
        for (; len; len--, w++)
            out[w] = out[w - dist];
    }
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Host proof: Chicago Ens insert adds multi-voice detune colour vs dry native303. */
#include <math.h>
#include <stdio.h>
#include <string.h>
#include "bass303.h"
#include "chicago_ens.h"
#include "chicago_fx.h"

static int fails;
#define CHECK(c, ...)                                                                                                  \
    do {                                                                                                               \
        if (!(c)) {                                                                                                    \
            printf("FAIL " __VA_ARGS__);                                                                               \
            printf("\n");                                                                                              \
            fails++;                                                                                                   \
        }                                                                                                              \
    } while (0)

static float buf[8192];
static float dry[8192];

static void render_note(bass303_t *b, float *out, int n)
{
    int pos = 0;
    bass303_init(b);
    bass303_set(b, BASS303_CUTOFF, 100);
    bass303_set(b, BASS303_RESO, 40);
    bass303_set(b, BASS303_ENVMOD, 0);
    bass303_set(b, BASS303_WAVE, 0);
    bass303_set(b, BASS303_GNAW, 0);
    bass303_set(b, BASS303_BITE, 0);
    bass303_set(b, BASS303_VOLUME, 100);
    bass303_set(b, BASS303_DRIVE, 0);
    bass303_set(b, BASS303_AMPMODE, BASS303_AMP_GATE);
    bass303_note_on_velocity(b, 48, 0, 0, 100);
    while (pos < n) {
        int m = n - pos > 128 ? 128 : n - pos;
        bass303_render(b, out + pos, m);
        pos += m;
    }
}

static double rms_delta(const float *a, const float *b, int n)
{
    double s = 0;
    int i;
    for (i = 0; i < n; i++) {
        double d = (double)a[i] - (double)b[i];
        s += d * d;
    }
    return sqrt(s / (double)n);
}

static void test_supported_flags(void)
{
    CHECK(chi_fx_supported(CHI_FX_ENS), "Ens supported");
    CHECK(chi_fx_is_insert(CHI_FX_ENS), "Ens is insert");
    CHECK(chi_fx_is_ens_insert(CHI_FX_ENS), "Ens ens-insert helper");
    CHECK(!chi_fx_is_not_yet(CHI_FX_ENS), "Ens not NOT_YET");
    CHECK(strstr(CHI_FX_TYPE_N[CHI_FX_ENS], "—") == 0, "Ens label has no em-dash");
}

static void test_map_clears_sends(void)
{
    chicago_fx_out_t o;
    chicago_fx_map(CHI_FX_ENS, 20, 80, 0, &o);
    CHECK(o.touch == CHI_FX_W_CLEAR_SENDS, "Ens insert clears sends");
    CHECK(!(o.touch & CHI_FX_W_MX_REV), "Ens does not set Mix reverb");
    CHECK(!(o.touch & CHI_FX_W_MX_DLY), "Ens does not set Mix delay");
}

static void test_ens_changes_pcm(void)
{
    bass303_t b;
    chi_ens_t ens;
    int n = 4096, skip = 512;
    double delta, delta_hi;
    render_note(&b, dry, n);

    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_ens_init(&ens);
    chi_ens_set(&ens, 20, 80, BASS303_SR); /* Italo Bass-ish */
    chi_ens_process(&ens, buf + skip, n - skip);
    delta = rms_delta(dry + skip, buf + skip, n - skip);
    CHECK(delta > 1e-4, "Ens changes waveform (rms delta %g)", delta);

    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_ens_init(&ens);
    chi_ens_set(&ens, 127, 127, BASS303_SR);
    chi_ens_process(&ens, buf + skip, n - skip);
    delta_hi = rms_delta(dry + skip, buf + skip, n - skip);
    CHECK(delta_hi > delta * 1.02, "higher wet/depth moves PCM more (lo %g hi %g)", delta, delta_hi);

    memcpy(buf, dry, (size_t)n * sizeof(float));
    chi_ens_init(&ens);
    chi_ens_process(&ens, buf + skip, n - skip);
    CHECK(memcmp(buf + skip, dry + skip, (size_t)(n - skip) * sizeof(float)) == 0,
          "unset Ens leaves PCM unchanged");
}

int main(void)
{
    test_supported_flags();
    test_map_clears_sends();
    test_ens_changes_pcm();
    if (fails) {
        printf("%d FAIL(s)\n", fails);
        return 1;
    }
    printf("PASS chicago_ens\n");
    return 0;
}

#!/usr/bin/env python3
"""Run the production corner decoder against independent 4x4 circle coverage."""
import os
from pathlib import Path
import re
import shlex
import subprocess
import tempfile


ROOT = Path(__file__).resolve().parents[2]
SOURCE = Path(os.environ.get('CORNER_SOURCE_FILE', ROOT / 'firmware/src/app/ui.c'))
text = SOURCE.read_text()


def extract(pattern):
    match = re.search(pattern, text, re.S | re.M)
    if not match:
        raise SystemExit('production corner table/decoder definition missing')
    return match.group(0)


definitions = '\n'.join([
    extract(r'^static const uint8_t CORNER_OFF\[[^\n]+;'),
    extract(r'^static const uint8_t CORNER_PACKED\[\d+\] = \{.*?^};'),
    extract(r'^static __attribute__\(\(noinline\)\) uint32_t corner_coverage\(uint32_t index\)\n\{.*?^}'),
    extract(r'^#define corner_fill_at[^\n]+'),
    extract(r'^#define corner_ring_at[^\n]+'),
])

# Count original geometric samples, independently of the nibble codec and table.
expected = []
for ring in (False, True):
    for radius in range(1, 9):
        for y in range(radius):
            for x in range(radius):
                coverage = 0
                for sy in range(4):
                    for sx in range(4):
                        dx = 8 * radius - 8 * x - 2 * sx - 1
                        dy = 8 * radius - 8 * y - 2 * sy - 1
                        distance = dx * dx + dy * dy
                        coverage += distance < 64 * radius * radius and (
                            not ring or distance >= 64 * (radius - 1) ** 2)
                expected.append(coverage)
assert len(expected) == 408
assert 8 not in expected and set(expected) == set(range(17)) - {8}

program = '''#include <stdint.h>
#include <stdio.h>
#define RMAX 8
''' + definitions + '\nstatic const uint8_t expected[408] = {' + ','.join(map(str, expected)) + '''};
int main(void)
{
    unsigned checks = 0;
    if (sizeof CORNER_PACKED != 204u) return 2;
    for (unsigned n = 0; n < 408; n++) {
        if (corner_coverage(n) != expected[n]) {
            fprintf(stderr, "corner %u: got %u expected %u\\n", n,
                    (unsigned)corner_coverage(n), (unsigned)expected[n]);
            return 1;
        }
        checks++;
    }
    unsigned n = 0;
    for (unsigned r = 1; r <= RMAX; r++)
        for (unsigned j = 0; j < r; j++)
            for (unsigned i = 0; i < r; i++) {
                if (corner_fill_at(r, j, i) != expected[n] ||
                    corner_ring_at(r, j, i) != expected[204u + n]) return 1;
                n++;
                checks += 2;
            }
    printf("corner coverage: %u production-decoder and geometry checks passed\\n", checks);
    return 0;
}
'''
with tempfile.TemporaryDirectory(prefix='x0x-corner-') as work:
    source = Path(work) / 'test.c'
    executable = Path(work) / 'test'
    source.write_text(program)
    subprocess.run([os.environ.get('CC', 'cc'), '-std=c99', '-O1', '-Wall', '-Wextra',
                    '-Werror', *shlex.split(os.environ.get('SAN_FLAGS', '')),
                    str(source), '-o', str(executable)], check=True)
    subprocess.run([str(executable)], check=True)

/* SPDX-License-Identifier: GPL-3.0-only */
/* Host extractors for smc_mixer.c: momentary SELECT FX calls sit in
 * smc_poll / smc_release / smc_project_reset; smc_knob toggles accel_smc around
 * turn_ref. Queue, Solo-overflow, link, BLE-reconnect-epoch and clip-visibility
 * harnesses do not exercise that stack — stub the entry points (and the panel
 * accel flag) so the real queue/link/clip regressions can compile and run. */
#pragma once
#include "app/smc_fx_map.h"
#include "app/smc_fx_map_tables.c" /* one map copy for single-file smc_mixer harnesses */

/* Solo / BLE-reconnect extractors omit smc_knob; queue/link/buttons still write it. */
static uint8_t __attribute__((unused)) accel_smc; /* production lives in ui.c */
static void __attribute__((unused)) smc_fx_main_tick(void) {}
static void __attribute__((unused)) smc_fx_clear(void) {}
static void __attribute__((unused)) smc_fx_release_note(uint8_t note) { (void)note; }
static void __attribute__((unused)) smc_fx_load_page(int page) { (void)page; }

/* These source-extracted queue fixtures do not exercise the lock gesture.
 * The production integration smc-lock-beat test owns its timer/loss coverage. */
static void __attribute__((unused)) smc_lock_tick(void) {}
